define(["jquery"],function($){var dragged=null;var updateOrder=function($list,$input){var ids=[];$list.children("[data-itemid]").each(function(){ids.push($(this).data("itemid"))});$input.val(ids.join(","))};var moveByKeyboard=function($item,direction){if(direction<0){var $previous=$item.prev();if($previous.length){$item.insertBefore($previous)}}else{var $next=$item.next();if($next.length){$item.insertAfter($next)}}};var init=function(listId,inputId){var $list=$("#"+listId);var $input=$("#"+inputId);if(!$list.length||!$input.length||$list.data("editable")!==1){return}$list.on("dragstart","[data-itemid]",function(event){dragged=this;event.originalEvent.dataTransfer.effectAllowed="move";event.originalEvent.dataTransfer.setData("text/plain",$(this).data("itemid"));$(this).addClass("opacity-50")});$list.on("dragend","[data-itemid]",function(){$(this).removeClass("opacity-50");dragged=null;updateOrder($list,$input)});$list.on("dragover","[data-itemid]",function(event){event.preventDefault();if(!dragged||dragged===this){return}var rect=this.getBoundingClientRect();var after=event.originalEvent.clientY>rect.top+rect.height/2;if(after){$(dragged).insertAfter(this)}else{$(dragged).insertBefore(this)}});$list.on("keydown","[data-itemid]",function(event){if(!event.altKey||event.key!=="ArrowUp"&&event.key!=="ArrowDown"){return}event.preventDefault();moveByKeyboard($(this),event.key==="ArrowUp"?-1:1);updateOrder($list,$input);this.focus()});updateOrder($list,$input)};return{init:init}});